// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// 本域进程存活
	// (GET /healthz)
	Health(ctx context.Context, request HealthRequestObject) (HealthResponseObject, error)
	// 本域启动/恢复就绪
	// (GET /readyz)
	Ready(ctx context.Context, request ReadyRequestObject) (ReadyResponseObject, error)
	// 读取资源分组
	// (GET /v1/asset-groups)
	ListAssetGroups(ctx context.Context, request ListAssetGroupsRequestObject) (ListAssetGroupsResponseObject, error)
	// 新建资源分组
	// (POST /v1/asset-groups)
	CreateAssetGroup(ctx context.Context, request CreateAssetGroupRequestObject) (CreateAssetGroupResponseObject, error)
	// 删除分组并保留资源
	// (DELETE /v1/asset-groups/{groupId})
	DeleteAssetGroup(ctx context.Context, request DeleteAssetGroupRequestObject) (DeleteAssetGroupResponseObject, error)
	// 内容域导入站点数据时交来的文件，一次完成声明、写入、校验与登记
	// (POST /v1/asset-imports)
	ImportAsset(ctx context.Context, request ImportAssetRequestObject) (ImportAssetResponseObject, error)
	// 资源库按类别列安全元数据，引用详情独立读取
	// (GET /v1/assets)
	ListAssets(ctx context.Context, request ListAssetsRequestObject) (ListAssetsResponseObject, error)
	// 后台单列当前未引用文件
	// (GET /v1/assets/unused)
	ListUnusedAssets(ctx context.Context, request ListUnusedAssetsRequestObject) (ListUnusedAssetsResponseObject, error)
	// 读取资源/variants安全元数据
	// (GET /v1/assets/{assetId})
	ReadAsset(ctx context.Context, request ReadAssetRequestObject) (ReadAssetResponseObject, error)
	// 鉴权读取immutable bytes和Range
	// (GET /v1/assets/{assetId}/bytes)
	ReadAssetBytes(ctx context.Context, request ReadAssetBytesRequestObject) (ReadAssetBytesResponseObject, error)
	// HEAD同GET授权只返header
	// (HEAD /v1/assets/{assetId}/bytes)
	HeadAssetBytes(ctx context.Context, request HeadAssetBytesRequestObject) (HeadAssetBytesResponseObject, error)
	// 移动资源到分组
	// (PUT /v1/assets/{assetId}/group)
	SetAssetGroup(ctx context.Context, request SetAssetGroupRequestObject) (SetAssetGroupResponseObject, error)
	// 列哪些文档当前/历史引用资源
	// (GET /v1/assets/{assetId}/references)
	ReadAssetReferences(ctx context.Context, request ReadAssetReferencesRequestObject) (ReadAssetReferencesResponseObject, error)
	// 关联浏览器多宽WebP原图
	// (PUT /v1/assets/{assetId}/variants)
	AttachImageVariants(ctx context.Context, request AttachImageVariantsRequestObject) (AttachImageVariantsResponseObject, error)
	// 取得可恢复的数据屏障
	// (POST /v1/barriers)
	AcquireBarrier(ctx context.Context, request AcquireBarrierRequestObject) (AcquireBarrierResponseObject, error)
	// 释放屏障
	// (DELETE /v1/barriers/{barrierId})
	ReleaseBarrier(ctx context.Context, request ReleaseBarrierRequestObject) (ReleaseBarrierResponseObject, error)
	// 列出还没结束的人工清理计划
	// (GET /v1/cleanup-plans)
	ListCleanupPlans(ctx context.Context, request ListCleanupPlansRequestObject) (ListCleanupPlansResponseObject, error)
	// 人工清理前生成精确风险计划
	// (POST /v1/cleanup-plans)
	ProposeManualCleanup(ctx context.Context, request ProposeManualCleanupRequestObject) (ProposeManualCleanupResponseObject, error)
	// 删除前取消人工清理
	// (DELETE /v1/cleanup-plans/{planId})
	CancelManualCleanup(ctx context.Context, request CancelManualCleanupRequestObject) (CancelManualCleanupResponseObject, error)
	// 管理员确认后进入迟到引用保护窗口
	// (POST /v1/cleanup-plans/{planId}:confirm)
	ConfirmManualCleanup(ctx context.Context, request ConfirmManualCleanupRequestObject) (ConfirmManualCleanupResponseObject, error)
	// 给公开/管理员预览返回SHA URLs/srcset/封面
	// (POST /v1/delivery-manifests)
	BuildDeliveryManifest(ctx context.Context, request BuildDeliveryManifestRequestObject) (BuildDeliveryManifestResponseObject, error)
	// 读取原资源清理任务恢复证明
	// (POST /v1/jobs/{jobId}/recovery)
	ReadJobRecovery(ctx context.Context, request ReadJobRecoveryRequestObject) (ReadJobRecoveryResponseObject, error)
	// 正文/config提交前保护资源迟到引用
	// (POST /v1/references:acquire)
	AcquireResourceReferences(ctx context.Context, request AcquireResourceReferencesRequestObject) (AcquireResourceReferencesResponseObject, error)
	// 源提交后确认pin为引用
	// (POST /v1/references:confirm)
	ConfirmResourceReferences(ctx context.Context, request ConfirmResourceReferencesRequestObject) (ConfirmResourceReferencesResponseObject, error)
	// 仅明确源未提交才释放pin
	// (POST /v1/references:release)
	ReleaseResourceReferences(ctx context.Context, request ReleaseResourceReferencesRequestObject) (ReleaseResourceReferencesResponseObject, error)
	// 受控读取已完成域快照归档
	// (GET /v1/snapshots/{snapshotId}/archive)
	ReadSnapshotArchive(ctx context.Context, request ReadSnapshotArchiveRequestObject) (ReadSnapshotArchiveResponseObject, error)
	// 删除恢复暂存或换出的旧数据目录
	// (POST /v1/snapshots:discard)
	DiscardSnapshot(ctx context.Context, request DiscardSnapshotRequestObject) (DiscardSnapshotResponseObject, error)
	// 导出屏障水位的一致快照
	// (POST /v1/snapshots:export)
	ExportSnapshot(ctx context.Context, request ExportSnapshotRequestObject) (ExportSnapshotResponseObject, error)
	// 暂存本域恢复归档，不改active目录
	// (POST /v1/snapshots:stage)
	StageSnapshot(ctx context.Context, request StageSnapshotRequestObject) (StageSnapshotResponseObject, error)
	// 开始内容寻址可续传上传
	// (POST /v1/uploads)
	BeginUpload(ctx context.Context, request BeginUploadRequestObject) (BeginUploadResponseObject, error)
	// 取消未完成上传释放配额
	// (DELETE /v1/uploads/{uploadId})
	AbortUpload(ctx context.Context, request AbortUploadRequestObject) (AbortUploadResponseObject, error)
	// 查询续传offset
	// (GET /v1/uploads/{uploadId})
	ReadUpload(ctx context.Context, request ReadUploadRequestObject) (ReadUploadResponseObject, error)
	// 顺序原子写有界上传块
	// (PUT /v1/uploads/{uploadId}/chunks)
	PutUploadChunk(ctx context.Context, request PutUploadChunkRequestObject) (PutUploadChunkResponseObject, error)
	// 完成hash/MIME验证后发布ready资源
	// (POST /v1/uploads/{uploadId}:complete)
	CompleteUpload(ctx context.Context, request CompleteUploadRequestObject) (CompleteUploadResponseObject, error)
	// 插入时一次获取平台公开信息并本地封面
	// (POST /v1/videos/metadata)
	ReadVideoMetadata(ctx context.Context, request ReadVideoMetadataRequestObject) (ReadVideoMetadataResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// Health operation middleware
func (sh *strictHandler) Health(w http.ResponseWriter, r *http.Request) {
	var request HealthRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.Health(ctx, request.(HealthRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "Health")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(HealthResponseObject); ok {
		if err := validResponse.VisitHealthResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

